# ---------------****** Fitting best distribution to the parameters ********--------------
# There are a couple of methods to estimate parameters of a distribution based on your data:
#          1) Maximum Likelihood Estimation (MLE), 2) Akaike information criterion (AIC),
#          3) Maximizing Bayesian Posterior Probability, etc.
#           SciPy performs parameter estimation using MLE.
#      Here we use the Kolmogorov-Smirnov Goodness-of-Fit Test (K-S Test)
result_of_dist = []


def best_dist(parameter):
    list_of_condists = ['alpha', 'anglit', 'arcsine', 'beta', 'betaprime', 'bradford', 'burr', 'burr12', 'cauchy',
                        'chi', 'chi2', 'cosine', 'dgamma', 'dweibull', 'erlang', 'expon', 'exponnorm', 'exponweib',
                        'exponpow', 'f', 'fatiguelife', 'fisk', 'foldcauchy', 'foldnorm', 'genlogistic', 'genpareto',
                        'gennorm', 'genexpon', 'genextreme', 'gausshyper', 'gamma', 'gengamma', 'genhalflogistic',
                        'gilbrat', 'gompertz', 'gumbel_r', 'gumbel_l', 'halfcauchy', 'halflogistic', 'halfnorm',
                        'halfgennorm', 'hypsecant', 'invgamma', 'invgauss', 'invweibull', 'johnsonsb', 'johnsonsu',
                        'kstwobign', 'laplace', 'levy', 'levy_l', 'logistic', 'loggamma', 'loglaplace', 'lognorm',
                        'lomax', 'maxwell', 'mielke', 'nakagami', 'ncx2', 'ncf', 'nct', 'norm', 'pareto', 'pearson3',
                        'powerlaw', 'powerlognorm', 'powernorm', 'rdist', 'reciprocal', 'rayleigh', 'rice',
                        'recipinvgauss', 'semicircular', 't', 'triang', 'truncexpon', 'truncnorm', 'tukeylambda',
                        'uniform', 'vonmises', 'vonmises_line', 'wald', 'weibull_min', 'weibull_max']
    results_con = []
    if parameter == 'CN':
        for i1 in list_of_condists:
            dist = getattr(stats, i1)
            param = dist.fit(CN)
            a = stats.kstest(CN, i1, args=param)
            results_con.append((i1, a[0], a[1]))
        results_con.sort(key=lambda x: float(x[2]), reverse=True)
        dist = getattr(stats, results_con[0][0])
        param = dist.fit(CN)
        result_of_dist.append(('CN', results_con[0][0], param, dist.numargs, dist.shapes))
        # dist1 = getattr(stats,results_con[0][0] )
        # sns.distplot(CN,fit = dist1, kde=False)
        # plt.title('CN')
        # plt.legend(results_con[0][0], loc='best')
        # plt.show()
        print("The best distribution for CN  is :", results_con[0][0])
        if results_con[0][2] == results_con[1][2]:
            print('Can Not Find the best distribution for CN')
    else:
        for i1 in list_of_condists:
            dist = getattr(stats, i1)
            param = dist.fit(pn[parameter])
            a = stats.kstest(pn[parameter], i1, args=param)
            results_con.append((i1, a[0], a[1]))
        results_con.sort(key=lambda x: float(x[2]), reverse=True)
        dist = getattr(stats, results_con[0][0])
        param = dist.fit(pn[parameter])
        result_of_dist.append((parameter, results_con[0][0], param, dist.numargs, dist.shapes))
        # dist1 = getattr(stats,results_con[0][0] )
        # sns.distplot(pn[parameter],fit = dist1, kde=False)
        # plt.title(parameter)
        # plt.legend(results_con[0][0], loc='best')
        # plt.show()
        print("The best distribution for  ", parameter, " is :", results_con[0][0])
        if results_con[0][2] == results_con[1][2]:
            print('Can Not Find the best distribution for', parameter)


