def pore_copulas(number):
    Z = np.random.multivariate_normal([0, 0, 0, 0], CorrPore, size=number, check_valid='ignore')
    # Generate multivariate random normal values
    U = stats.norm.cdf(Z, loc=0, scale=1)
    # Obtain normal cumulative distribution function of values of Z
    for i in range(4):
        if result_of_dist[i][3] == 4:  # For fitted distributions that have 4 shape parameter
            F = getattr(stats, result_of_dist[i][1])
            X[:, i] = F.ppf(U[:, i], result_of_dist[i][2][0], result_of_dist[i][2][1], result_of_dist[i][2][2],
                            result_of_dist[i][2][3], loc=result_of_dist[i][2][4], scale=result_of_dist[i][2][5])
        elif result_of_dist[i][3] == 3:  # For fitted distributions that have 3 shape parameter
            F = getattr(stats, result_of_dist[i][1])
            X[:, i] = F.ppf(U[:, i], result_of_dist[i][2][0], result_of_dist[i][2][1], result_of_dist[i][2][2],
                            loc=result_of_dist[i][2][3], scale=result_of_dist[i][2][4])
        elif result_of_dist[i][3] == 2:  # For fitted distributions that have 2 shape parameter
            F = getattr(stats, result_of_dist[i][1])
            X[:, i] = F.ppf(U[:, i], result_of_dist[i][2][0], result_of_dist[i][2][1], loc=result_of_dist[i][2][2],
                            scale=result_of_dist[i][2][3])
        elif result_of_dist[i][3] == 1:  # For fitted distributions that have 1 shape parameter
            F = getattr(stats, result_of_dist[i][1])
            X[:, i] = F.ppf(U[:, i], result_of_dist[i][2][0], loc=result_of_dist[i][2][1],
                            scale=result_of_dist[i][2][2])
        else:  # For fitted distributions that have 0 shape parameter
            F = getattr(stats, result_of_dist[i][1])
            X[:, i] = F.ppf(U[:, i], loc=result_of_dist[i][2][0], scale=result_of_dist[i][2][1])
    X[:, 2] = np.ceil(X[:, 2])  # Coordination number must be discrete number


def throat_copulas(number):
    Z_thr = np.random.multivariate_normal([0, 0, 0], CorrThroat, size=number, check_valid='ignore')
    U_thr = stats.norm.cdf(Z_thr, loc=0, scale=1)

    for i in range(4, 7):
        if result_of_dist[i][3] == 4:
            F = getattr(stats, result_of_dist[i][1])
            X_thr[:, i - 4] = F.ppf(U_thr[:, i - 4], result_of_dist[i][2][0], result_of_dist[i][2][1],
                                    result_of_dist[i][2][2], result_of_dist[i][2][3], loc=result_of_dist[i][2][4],
                                    scale=result_of_dist[i][2][5])
        elif result_of_dist[i][3] == 3:
            F = getattr(stats, result_of_dist[i][1])
            X_thr[:, i - 4] = F.ppf(U_thr[:, i - 4], result_of_dist[i][2][0], result_of_dist[i][2][1],
                                    result_of_dist[i][2][2], loc=result_of_dist[i][2][3],
                                    scale=result_of_dist[i][2][4])
        elif result_of_dist[i][3] == 2:
            F = getattr(stats, result_of_dist[i][1])
            X_thr[:, i - 4] = F.ppf(U_thr[:, i - 4], result_of_dist[i][2][0], result_of_dist[i][2][1],
                                    loc=result_of_dist[i][2][2], scale=result_of_dist[i][2][3])
        elif result_of_dist[i][3] == 1:
            F = getattr(stats, result_of_dist[i][1])
            X_thr[:, i - 4] = F.ppf(U_thr[:, i - 4], result_of_dist[i][2][0], loc=result_of_dist[i][2][1],
                                    scale=result_of_dist[i][2][2])
        else:
            F = getattr(stats, result_of_dist[i][1])
            X_thr[:, i - 4] = F.ppf(U_thr[:, i - 4], loc=result_of_dist[i][2][0], scale=result_of_dist[i][2][1])


